
package com.tauqeet.library.astronomy

import kotlin.math.cos

class EarthHeliocentricState(
    val longitude: Double,
    val latitude: Double,
    val radius: Double
)

/**
 * Evaluates a single VSOP87 trigonometric series using 3 parallel DoubleArrays.
 *
 * Implements a 2-lane unrolled Kahan compensated summation to eliminate
 * loop-carried dependencies (pipeline stalls), increasing ILP.
 *
 * Complexity: O(N) time, O(1) space.
 */
fun seriesSum(tau: Double, A: DoubleArray, B: DoubleArray, C: DoubleArray): Double {
    var sum1 = 0.0
    var cComp1 = 0.0
    var sum2 = 0.0
    var cComp2 = 0.0
    val len = A.size
    var i = 0

    while (i <= len - 2) {
        // Lane 1
        val val1 = A[i] * cos(B[i] + tau * C[i])
        val y1 = val1 - cComp1
        val t1 = sum1 + y1
        cComp1 = t1 - sum1 - y1
        sum1 = t1

        // Lane 2
        val val2 = A[i + 1] * cos(B[i + 1] + tau * C[i + 1])
        val y2 = val2 - cComp2
        val t2 = sum2 + y2
        cComp2 = t2 - sum2 - y2
        sum2 = t2

        i += 2
    }

    // Remainder
    while (i < len) {
        val val1 = A[i] * cos(B[i] + tau * C[i])
        val y1 = val1 - cComp1
        val t1 = sum1 + y1
        cComp1 = t1 - sum1 - y1
        sum1 = t1
        i++
    }

    // Merge the two accumulators safely using Kahan
    val yFinal = sum2 - cComp1
    val tFinal = sum1 + yFinal
    val finalSum = tFinal - cComp2

    return finalSum
}

private fun sumSeriesParallel(series: ParallelSeries, tau: Double): Double {
    return seriesSum(tau, series.A, series.B, series.C)
}

fun computeEarthHeliocentricState(tau: Double): EarthHeliocentricState {
    val sumL0 = sumSeriesParallel(L0, tau)
    val sumL1 = sumSeriesParallel(L1, tau)
    val sumL2 = sumSeriesParallel(L2, tau)
    val sumL3 = sumSeriesParallel(L3, tau)
    val sumL4 = sumSeriesParallel(L4, tau)
    val sumL5 = sumSeriesParallel(L5, tau)
    val longitude = sumL0 + tau * (sumL1 + tau * (sumL2 + tau * (sumL3 + tau * (sumL4 + tau * sumL5))))

    val sumB0 = sumSeriesParallel(B0, tau)
    val sumB1 = sumSeriesParallel(B1, tau)
    val sumB2 = sumSeriesParallel(B2, tau)
    val sumB3 = sumSeriesParallel(B3, tau)
    val sumB4 = sumSeriesParallel(B4, tau)
    val latitude = sumB0 + tau * (sumB1 + tau * (sumB2 + tau * (sumB3 + tau * sumB4)))

    val sumR0 = sumSeriesParallel(R0, tau)
    val sumR1 = sumSeriesParallel(R1, tau)
    val sumR2 = sumSeriesParallel(R2, tau)
    val sumR3 = sumSeriesParallel(R3, tau)
    val sumR4 = sumSeriesParallel(R4, tau)
    val sumR5 = sumSeriesParallel(R5, tau)
    val radius = sumR0 + tau * (sumR1 + tau * (sumR2 + tau * (sumR3 + tau * (sumR4 + tau * sumR5))))

    return EarthHeliocentricState(
        longitude = longitude,
        latitude = latitude,
        radius = radius
    )
}


